# Hindi / Gujarati text for Geography Ch 1 lesson, sections 4-7.
TEXT_B = {
 "s4.thm.title": ("भू-उपयोग और भूमि निम्नीकरण", "ભૂમિ ઉપયોગ અને ભૂમિ અવક્રમણ"),
 "s4.thm.body": (
  "भूमि **अत्यंत महत्त्वपूर्ण प्राकृतिक संसाधन** है: यह प्राकृतिक वनस्पति, वन्य जीवन, मानव जीवन, आर्थिक क्रियाओं, परिवहन और संचार व्यवस्थाओं का आधार है। चूँकि भूमि **सीमित** है, इसलिए इसका उपयोग सावधानी और योजनाबद्ध तरीक़े से करना चाहिए।\n\n"
  "भारत में विविध भू-आकृतियाँ हैं: लगभग **43 प्रतिशत** भू-क्षेत्र **मैदान** है, जो कृषि और उद्योग के विकास की सुविधाएँ देता है; **पर्वत** लगभग **30 प्रतिशत** हैं, जो कुछ बारहमासी नदियों के प्रवाह, पर्यटन और पारिस्थितिकी को सुनिश्चित करते हैं; लगभग **27 प्रतिशत** भाग **पठार** है, जिसमें खनिजों, जीवाश्म ईंधनों और वनों के समृद्ध भंडार हैं।\n\n"
  "**भारत में भू-उपयोग प्रारूप:** भू-उपयोग **भौतिक कारकों** (भू-आकृति, जलवायु, मृदा के प्रकार) और **मानवीय कारकों** (जनसंख्या घनत्व, प्रौद्योगिकी क्षमता, संस्कृति और परंपराएँ) से निर्धारित होता है। "
  "भारत का कुल भौगोलिक क्षेत्रफल **32.8 लाख वर्ग किमी** है, पर भू-उपयोग के आँकड़े केवल लगभग **93 प्रतिशत** क्षेत्र के ही उपलब्ध हैं, क्योंकि असम को छोड़कर अधिकांश पूर्वोत्तर राज्यों में भू-उपयोग की सूचना पूरी तरह उपलब्ध नहीं है, और जम्मू-कश्मीर के पाकिस्तान और चीन अधिकृत कुछ क्षेत्रों का सर्वेक्षण नहीं हुआ है।\n"
  "- शुद्ध (निवल) बोए गए क्षेत्र में बहुत अंतर है: **पंजाब और हरियाणा** में यह कुल क्षेत्र का **80 प्रतिशत से अधिक** है, जबकि **अरुणाचल प्रदेश, मिज़ोरम, मणिपुर और अंडमान-निकोबार द्वीपसमूह** में **10 प्रतिशत से कम**।\n"
  "- वन क्षेत्र **राष्ट्रीय वन नीति (1952)** द्वारा निर्धारित भौगोलिक क्षेत्र के **33 प्रतिशत** से बहुत कम है, जिसे पारिस्थितिकी संतुलन बनाए रखने के लिए आवश्यक माना गया है। वनों के आसपास रहने वाले बहुत-से लोगों की आजीविका वनों पर निर्भर है।\n"
  "- **स्थायी चरागाहों** के अंतर्गत भूमि घटी है; लंबे समय तक **परती** छोड़ी गई भूमि का निम्नीकरण हो सकता है; और नगरों और उद्योगों के बढ़ने से ग़ैर-कृषि उपयोग की भूमि बढ़ी है।\n\n"
  "**भूमि निम्नीकरण:** मानवीय क्रियाओं ने भूमि का निम्नीकरण किया है और प्राकृतिक ताक़तों ने उसे बढ़ाया है। भारत में लगभग **13 करोड़ हेक्टेयर** भूमि निम्नीकृत है: इसका लगभग **28 प्रतिशत** निम्नीकृत वन क्षेत्र है, **56 प्रतिशत** जल अपरदित क्षेत्र है, और शेष **लवणीय और क्षारीय** है।\n"
  "- **खनन:** **झारखंड, छत्तीसगढ़, मध्य प्रदेश और ओडिशा** में खनन के कारण वनोन्मूलन से भूमि का गंभीर निम्नीकरण हुआ है; खुदाई के बाद खदानों को छोड़ दिया जाता है, जिससे गहरी खाइयाँ और मलबा रह जाता है।\n"
  "- **अति पशुचारण:** **गुजरात, राजस्थान, मध्य प्रदेश और महाराष्ट्र** में अति पशुचारण भूमि निम्नीकरण का मुख्य कारण है।\n"
  "- **अति सिंचाई:** **पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश** में अति सिंचाई से **जलाक्रांतता** होती है, जिससे मृदा में **लवणता और क्षारता** बढ़ती है।\n"
  "- **खनिज प्रक्रियाएँ:** सीमेंट उद्योग में चूना पत्थर को पीसने और मृदा-बर्तन उद्योग में चूने (कैल्साइट) और सेलखड़ी के प्रयोग से भारी मात्रा में धूल बनती है, जो भूमि पर जमकर जल के अंतःस्रवण को धीमा कर देती है।\n"
  "- **औद्योगिक जल निकास** भूमि और जल प्रदूषण का प्रमुख स्रोत बन गया है।\n\n"
  "**भूमि निम्नीकरण के समाधान:** वनारोपण और चरागाहों का उचित प्रबंधन; पेड़ों की **रक्षक मेखला**; पशुचारण पर नियंत्रण; काँटेदार झाड़ियाँ लगाकर **रेतीले टीलों का स्थिरीकरण**; बंजर भूमि का उचित प्रबंधन; खनन पर नियंत्रण; और औद्योगिक जल और अपशिष्ट का परिष्करण के बाद उचित निपटान।",
  "ભૂમિ **અત્યંત મહત્ત્વનું કુદરતી સંસાધન** છે: તે કુદરતી વનસ્પતિ, વન્યજીવન, માનવજીવન, આર્થિક પ્રવૃત્તિઓ, પરિવહન અને સંદેશાવ્યવહારનો આધાર છે. ભૂમિ **મર્યાદિત** હોવાથી તેનો ઉપયોગ કાળજી અને આયોજનપૂર્વક કરવો જોઈએ.\n\n"
  "ભારતમાં વિવિધ ભૂમિસ્વરૂપો છે: આશરે **43 ટકા** ભૂમિ વિસ્તાર **મેદાનો** છે, જે ખેતી અને ઉદ્યોગના વિકાસની સુવિધા આપે છે; **પર્વતો** આશરે **30 ટકા** છે, જે કેટલીક બારમાસી નદીઓના પ્રવાહ, પ્રવાસન અને પર્યાવરણ સુનિશ્ચિત કરે છે; આશરે **27 ટકા** ભાગ **ઉચ્ચપ્રદેશ** છે, જેમાં ખનિજો, અશ્મિ ઇંધણો અને જંગલોના સમૃદ્ધ ભંડાર છે.\n\n"
  "**ભારતમાં ભૂમિ ઉપયોગની ભાત:** ભૂમિ ઉપયોગ **ભૌતિક પરિબળો** (ભૂપૃષ્ઠ, આબોહવા, જમીનના પ્રકારો) અને **માનવીય પરિબળો** (વસ્તી ગીચતા, ટેકનોલોજીની ક્ષમતા, સંસ્કૃતિ અને પરંપરાઓ) દ્વારા નક્કી થાય છે. "
  "ભારતનું કુલ ભૌગોલિક ક્ષેત્રફળ **32.8 લાખ ચો. કિમી** છે, પણ ભૂમિ ઉપયોગના આંકડા ફક્ત આશરે **93 ટકા** વિસ્તારના જ ઉપલબ્ધ છે, કારણ કે આસામ સિવાયનાં મોટા ભાગનાં ઈશાન રાજ્યોમાં ભૂમિ ઉપયોગની માહિતી પૂરી મળી નથી, અને જમ્મુ-કાશ્મીરના પાકિસ્તાન અને ચીનના કબજાવાળા કેટલાક વિસ્તારોનું સર્વેક્ષણ થયું નથી.\n"
  "- ચોખ્ખા વાવેતર વિસ્તારમાં ઘણો તફાવત છે: **પંજાબ અને હરિયાણા**માં તે કુલ વિસ્તારના **80 ટકાથી વધુ** છે, જ્યારે **અરુણાચલ પ્રદેશ, મિઝોરમ, મણિપુર અને આંદામાન-નિકોબાર ટાપુઓ**માં **10 ટકાથી ઓછો**.\n"
  "- જંગલ વિસ્તાર **રાષ્ટ્રીય વનનીતિ (1952)** દ્વારા નક્કી કરાયેલા ભૌગોલિક વિસ્તારના **33 ટકા**થી ઘણો ઓછો છે, જે પર્યાવરણીય સંતુલન જાળવવા જરૂરી ગણાય છે. જંગલોની આસપાસ રહેતા ઘણા લોકોની આજીવિકા જંગલો પર આધારિત છે.\n"
  "- **કાયમી ગોચર** હેઠળની જમીન ઘટી છે; લાંબા સમય સુધી **પડતર** રાખેલી જમીનનું અવક્રમણ થઈ શકે; અને નગરો અને ઉદ્યોગો વધતાં બિનખેતી ઉપયોગની જમીન વધી છે.\n\n"
  "**ભૂમિ અવક્રમણ:** માનવ પ્રવૃત્તિઓએ ભૂમિનું અવક્રમણ કર્યું છે અને કુદરતી બળોએ તેને વધાર્યું છે. ભારતમાં આશરે **13 કરોડ હેક્ટર** ભૂમિ અવક્રમિત છે: તેનો આશરે **28 ટકા** અવક્રમિત જંગલ વિસ્તાર છે, **56 ટકા** પાણીથી ધોવાયેલો વિસ્તાર છે, અને બાકીનો **ક્ષારીય અને આલ્કલાઇન** છે.\n"
  "- **ખાણકામ:** **ઝારખંડ, છત્તીસગઢ, મધ્ય પ્રદેશ અને ઓડિશા**માં ખાણકામને કારણે જંગલો કપાતાં ભૂમિનું ગંભીર અવક્રમણ થયું છે; ખોદકામ પછી ખાણો છોડી દેવાય છે, જેથી ઊંડા ખાડા અને કચરાના ઢગ રહી જાય છે.\n"
  "- **અતિચરાઈ:** **ગુજરાત, રાજસ્થાન, મધ્ય પ્રદેશ અને મહારાષ્ટ્ર**માં અતિચરાઈ ભૂમિ અવક્રમણનું મુખ્ય કારણ છે.\n"
  "- **અતિસિંચાઈ:** **પંજાબ, હરિયાણા અને પશ્ચિમ ઉત્તર પ્રદેશ**માં અતિસિંચાઈથી **જમીન પાણીથી ભરાઈ જાય** છે, જેથી જમીનમાં **ક્ષારતા અને આલ્કલાઇનતા** વધે છે.\n"
  "- **ખનિજ પ્રક્રિયાઓ:** સિમેન્ટ ઉદ્યોગ માટે ચૂનાનો પથ્થર દળવાથી અને સિરામિક ઉદ્યોગ માટે કૅલ્સાઇટ અને સોપસ્ટોન (સેલખડી)થી પુષ્કળ ધૂળ બને છે, જે જમીન પર જામીને પાણીના શોષણને ધીમું કરે છે.\n"
  "- **ઔદ્યોગિક કચરાયુક્ત પાણી** ભૂમિ અને જળ પ્રદૂષણનો મુખ્ય સ્રોત બન્યું છે.\n\n"
  "**ભૂમિ અવક્રમણના ઉકેલો:** વનીકરણ અને ગોચરનું યોગ્ય વ્યવસ્થાપન; વૃક્ષોની **રક્ષક પટ્ટીઓ**; ચરાઈ પર નિયંત્રણ; કાંટાળાં ઝાડવાં વાવીને **રેતીના ઢૂવાઓનું સ્થિરીકરણ**; પડતર જમીનનું યોગ્ય વ્યવસ્થાપન; ખાણકામ પર નિયંત્રણ; અને ઔદ્યોગિક પાણી અને કચરાનો શુદ્ધીકરણ પછી યોગ્ય નિકાલ."),
 "s4.landuse.title": ("भू-उपयोग की श्रेणियाँ", "ભૂમિ ઉપયોગની શ્રેણીઓ"),
 "s4.landuse.body": (
  "| श्रेणी | इसमें क्या शामिल है |\n|---|---|\n| 1. वन | वनों के अंतर्गत भूमि |\n| 2. कृषि के लिए अनुपलब्ध भूमि | (क) बंजर और व्यर्थ भूमि; (ख) ग़ैर-कृषि प्रयोजनों में लगाई गई भूमि: इमारतें, सड़कें, उद्योग |\n"
  "| 3. परती भूमि के अतिरिक्त अन्य कृषि अयोग्य भूमि | (क) स्थायी चरागाहें और अन्य गोचर भूमि; (ख) विविध वृक्षों, वृक्ष फ़सलों और उपवनों के अधीन भूमि; (ग) कृषि योग्य बंजर भूमि जो 5 से अधिक वर्षों से जोती नहीं गई |\n"
  "| 4. परती भूमि | (क) वर्तमान परती: एक कृषि वर्ष या उससे कम समय से बिना खेती; (ख) वर्तमान परती भूमि के अतिरिक्त अन्य परती: 1 से 5 कृषि वर्षों से बिना खेती |\n"
  "| 5. शुद्ध (निवल) बोया गया क्षेत्र | एक कृषि वर्ष में फ़सल बोया गया क्षेत्र; **सकल कृषित क्षेत्र** = शुद्ध बोया गया क्षेत्र + एक से अधिक बार बोया गया क्षेत्र |",
  "| શ્રેણી | તેમાં શું આવે |\n|---|---|\n| 1. જંગલો | જંગલ હેઠળની જમીન |\n| 2. ખેતી માટે અપ્રાપ્ય જમીન | (ક) ઉજ્જડ અને નકામી જમીન; (ખ) બિનખેતી ઉપયોગમાં લેવાયેલી જમીન: ઇમારતો, રસ્તા, ઉદ્યોગો |\n"
  "| 3. પડતર સિવાયની બિનખેડાણ જમીન | (ક) કાયમી ગોચર અને ચરાણ જમીન; (ખ) પરચૂરણ વૃક્ષ પાકો અને ઉપવનો હેઠળની જમીન; (ગ) ખેતીલાયક ઉજ્જડ જમીન જે 5થી વધુ વર્ષથી ખેડાઈ નથી |\n"
  "| 4. પડતર જમીન | (ક) ચાલુ પડતર: એક કૃષિ વર્ષ કે તેથી ઓછા સમયથી ખેડાઈ નથી; (ખ) ચાલુ પડતર સિવાયની પડતર: 1થી 5 કૃષિ વર્ષથી ખેડાઈ નથી |\n"
  "| 5. ચોખ્ખો વાવેતર વિસ્તાર | એક વર્ષમાં પાક વાવેલો વિસ્તાર; **કુલ પાક વિસ્તાર** = ચોખ્ખો વાવેતર વિસ્તાર + એકથી વધુ વાર વાવેલો વિસ્તાર |"),
 "s5.thm.title": ("मृदा कैसे बनती है और भारत की मृदाएँ", "જમીન કેવી રીતે બને છે અને ભારતની જમીનો"),
 "s5.thm.body": (
  "मृदा सबसे महत्त्वपूर्ण **नवीकरण योग्य प्राकृतिक संसाधन** है: यह पौधों के विकास का माध्यम है और विभिन्न प्रकार के जीवों का पोषण करती है। मृदा एक जीवंत तंत्र है। कुछ सेंटीमीटर गहरी मृदा बनने में **लाखों वर्ष** लग जाते हैं।\n\n"
  "**मृदा निर्माण के कारक:** **उच्चावच, जनक शैल या संस्तर शैल, जलवायु, वनस्पति और अन्य जैव पदार्थ, और समय**। तापमान परिवर्तन, बहते जल, पवन और हिमनदों की क्रियाएँ और अपघटकों की गतिविधियाँ मृदा निर्माण में योगदान देती हैं। मृदा में होने वाले रासायनिक और जैविक परिवर्तन भी उतने ही महत्त्वपूर्ण हैं। मृदा जैव (ह्यूमस) और अजैव दोनों प्रकार के पदार्थों से बनती है।\n\n"
  "**1. जलोढ़ मृदा:** यह **सबसे विस्तृत** और महत्त्वपूर्ण मृदा है। संपूर्ण **उत्तरी मैदान** जलोढ़ मृदा से बना है, जिसे हिमालय के तीन नदी तंत्रों, **सिंधु, गंगा और ब्रह्मपुत्र** ने जमा किया है। यह एक सँकरे गलियारे से **राजस्थान और गुजरात** तक फैली है, और पूर्वी तटीय मैदानों में, विशेषकर **महानदी, गोदावरी, कृष्णा और कावेरी के डेल्टाओं** में मिलती है।\n"
  "- इसमें **रेत, सिल्ट और मृत्तिका** विभिन्न अनुपात में होते हैं। नदी घाटी के ऊपरी भाग में, ढाल भंग के समीप, मृदा के कण बड़े होते हैं; **दुआर, चो और तराई** जैसे गिरिपद मैदानों में मोटे कणों वाली मृदा पाई जाती है।\n"
  "- आयु के आधार पर यह **पुरानी जलोढ़ (बांगर)** है, जिसमें **कंकड़ ग्रंथियों** की मात्रा अधिक होती है, और **नई जलोढ़ (खादर)**, जिसमें महीन कण अधिक होते हैं, और जो बांगर से **अधिक उपजाऊ** है।\n"
  "- यह बहुत उपजाऊ है, इसमें **पोटाश, फ़ॉस्फ़ोरस और चूना** पर्याप्त मात्रा में होता है, जो इसे **गन्ने, चावल, गेहूँ और अन्य अनाज और दलहन फ़सलों** के लिए उपयुक्त बनाता है। इसलिए ये क्षेत्र **गहन कृषि वाले और घनी आबादी वाले** हैं। सूखे क्षेत्रों की मृदाएँ अधिक क्षारीय हैं, जिन्हें उचित उपचार और सिंचाई से उपजाऊ बनाया जा सकता है।\n\n"
  "**2. काली मृदा (रेगर मृदा):** इसका रंग काला है और यह **कपास** की खेती के लिए उचित है, इसलिए इसे **काली कपास मृदा** भी कहते हैं। इसके निर्माण में जलवायु और **जनक शैलों** का महत्त्वपूर्ण योगदान है: यह **लावा प्रवाह (बेसाल्ट)** से बनी है और उत्तर-पश्चिमी दक्कन पठार पर फैले **दक्कन ट्रैप** क्षेत्र की विशिष्ट मृदा है।\n"
  "- यह **महाराष्ट्र, सौराष्ट्र, मालवा, मध्य प्रदेश और छत्तीसगढ़** के पठारों पर पाई जाती है, और दक्षिण-पूर्व दिशा में **गोदावरी और कृष्णा की घाटियों** तक फैली है।\n"
  "- यह बहुत महीन कणों (**मृत्तिका**) से बनी है और **नमी धारण करने** की क्षमता के लिए जानी जाती है; इसमें **कैल्शियम कार्बोनेट, मैग्नीशियम, पोटाश और चूना** भरपूर है, पर **फ़ॉस्फ़ोरस की मात्रा कम** है।\n"
  "- **गर्म और शुष्क मौसम में इसमें गहरी दरारें** पड़ जाती हैं, जिससे इसमें अच्छी तरह **वायु मिश्रण** होता है; **गीली होने पर यह चिपचिपी** हो जाती है और इस पर काम करना कठिन होता है, जब तक कि पहली बारिश के तुरंत बाद या मानसून-पूर्व काल में इसकी जुताई न की जाए।\n\n"
  "**3. लाल और पीली मृदा:** दक्कन पठार के पूर्वी और दक्षिणी हिस्सों में कम वर्षा वाले क्षेत्रों में **रवेदार आग्नेय चट्टानों** पर विकसित होती है; **ओडिशा, छत्तीसगढ़, मध्य गंगा मैदान के दक्षिणी छोर** और **पश्चिमी घाट के गिरिपद क्षेत्र** में भी पाई जाती है। "
  "रवेदार और कायांतरित चट्टानों में **लोहे के व्यापक विसरण** के कारण इसका रंग **लाल** है, और **जलयोजित होने पर यह पीली** दिखती है।\n\n"
  "**4. लेटराइट मृदा:** यह लैटिन शब्द **'लेटर' (ईंट)** से बना है। यह **उच्च तापमान और भारी वर्षा** वाले क्षेत्रों में विकसित होती है, और भारी वर्षा से हुए **तीव्र निक्षालन** का परिणाम है। उच्च तापमान में आसानी से नष्ट हो जाने वाले जीवाणु जैसे अपघटकों के कारण इसमें **ह्यूमस कम** होता है। "
  "यह मुख्य रूप से **कर्नाटक, केरल, तमिलनाडु, मध्य प्रदेश** और **ओडिशा और असम** के पहाड़ी क्षेत्रों में पाई जाती है। मृदा संरक्षण की उचित तकनीक अपनाकर, विशेषकर पहाड़ी क्षेत्रों में, यह **चाय और कॉफ़ी** के लिए बहुत उपयोगी है; **तमिलनाडु, आंध्र प्रदेश और केरल** की लाल लेटराइट मृदाएँ **काजू** की फ़सल के लिए अधिक उपयुक्त हैं।\n\n"
  "**5. मरुस्थली मृदा:** इसका रंग **लाल से भूरा** होता है; यह सामान्यतः **रेतीली** और **लवणीय** होती है; कुछ क्षेत्रों में नमक की मात्रा इतनी अधिक है कि झीलों के पानी को वाष्पीकृत करके नमक बनाया जाता है। शुष्क जलवायु और उच्च तापमान के कारण जल वाष्पन दर अधिक है और मृदा में **ह्यूमस और नमी की मात्रा कम** है। "
  "मृदा की निचली परतों में चूने के बढ़ते अंश के कारण **कंकड़** की परत पाई जाती है, जो पानी के रिसाव को सीमित करती है। उचित **सिंचाई** से ये मृदाएँ उपजाऊ बनाई जा सकती हैं, जैसे **पश्चिमी राजस्थान** में।\n\n"
  "**6. वन मृदा:** ये **पहाड़ी और पर्वतीय क्षेत्रों** में पाई जाती हैं जहाँ पर्याप्त वर्षा वन उपलब्ध हैं। इनका गठन पर्वतीय पर्यावरण के अनुसार बदलता है: नदी घाटियों में ये **दोमट और सिल्टदार** और ऊपरी ढलानों पर **मोटे कणों** वाली होती हैं। हिमालय के हिमाच्छादित क्षेत्रों में इनका अनाच्छादन होता है और ये **अम्लीय और कम ह्यूमस** वाली होती हैं; नदी घाटियों के निचले भागों में, विशेषकर **नदी सोपानों और जलोढ़ पंखों** में, ये उपजाऊ होती हैं।",
  "જમીન સૌથી મહત્ત્વનું **પુનઃપ્રાપ્ય કુદરતી સંસાધન** છે: તે વનસ્પતિના વિકાસનું માધ્યમ છે અને વિવિધ સજીવોને પોષે છે. જમીન એક જીવંત તંત્ર છે. થોડા સેન્ટિમીટર ઊંડી જમીન બનતાં **લાખો વર્ષ** લાગે છે.\n\n"
  "**જમીન નિર્માણનાં પરિબળો:** **ભૂપૃષ્ઠ, મૂળ ખડક કે પાયાનો ખડક, આબોહવા, વનસ્પતિ અને અન્ય જીવસૃષ્ટિ, અને સમય**. તાપમાનમાં ફેરફાર, વહેતાં પાણી, પવન અને હિમનદીઓની ક્રિયાઓ અને વિઘટકોની પ્રવૃત્તિઓ જમીન નિર્માણમાં ફાળો આપે છે. જમીનમાં થતા રાસાયણિક અને જૈવિક ફેરફારો પણ એટલા જ મહત્ત્વના છે. જમીન જૈવિક (સેન્દ્રિય દ્રવ્ય) અને અજૈવિક બંને પ્રકારના પદાર્થોથી બને છે.\n\n"
  "**1. કાંપની જમીન:** આ **સૌથી વ્યાપક** અને મહત્ત્વની જમીન છે. સમગ્ર **ઉત્તરનાં મેદાનો** કાંપની જમીનથી બનેલાં છે, જે હિમાલયની ત્રણ નદી પ્રણાલીઓ, **સિંધુ, ગંગા અને બ્રહ્મપુત્ર**એ જમા કરી છે. તે એક સાંકડા પટ્ટા દ્વારા **રાજસ્થાન અને ગુજરાત** સુધી ફેલાયેલી છે, અને પૂર્વના કિનારાનાં મેદાનોમાં, ખાસ કરીને **મહાનદી, ગોદાવરી, કૃષ્ણા અને કાવેરીના મુખત્રિકોણો**માં મળે છે.\n"
  "- તેમાં **રેતી, કાંપ (સિલ્ટ) અને માટી** જુદા જુદા પ્રમાણમાં હોય છે. નદીખીણના ઉપરવાસમાં, ઢોળાવ બદલાય તે સ્થળની નજીક, જમીનના કણો મોટા હોય છે; **દુઆર, ચો અને તરાઈ** જેવાં તળેટીનાં મેદાનોમાં જાડા કણોવાળી જમીન જોવા મળે છે.\n"
  "- ઉંમરના આધારે તે **જૂની કાંપની જમીન (બાંગર)** છે, જેમાં **કંકર ગઠ્ઠાઓ** વધુ હોય છે, અને **નવી કાંપની જમીન (ખાદર)**, જેમાં ઝીણા કણો વધુ હોય છે, અને જે બાંગર કરતાં **વધુ ફળદ્રુપ** છે.\n"
  "- તે ખૂબ ફળદ્રુપ છે, તેમાં **પોટાશ, ફૉસ્ફરિક ઍસિડ અને ચૂનો** પૂરતા પ્રમાણમાં છે, જે તેને **શેરડી, ડાંગર, ઘઉં અને અન્ય ધાન્ય અને કઠોળ પાકો** માટે ઉત્તમ બનાવે છે. તેથી આ વિસ્તારો **સઘન ખેતીવાળા અને ગીચ વસ્તીવાળા** છે. સૂકા વિસ્તારોની જમીનો વધુ આલ્કલાઇન છે, જેને યોગ્ય ઉપચાર અને સિંચાઈથી ઉત્પાદક બનાવી શકાય.\n\n"
  "**2. કાળી જમીન (રેગુર જમીન):** તેનો રંગ કાળો છે અને તે **કપાસ**ની ખેતી માટે ઉત્તમ છે, તેથી તેને **કાળી કપાસની જમીન** પણ કહે છે. તેના નિર્માણમાં આબોહવા અને **મૂળ ખડક**નું મહત્ત્વનું યોગદાન છે: તે **લાવાના પ્રવાહ (બેસાલ્ટ)**થી બનેલી છે અને ઉત્તર-પશ્ચિમ દખ્ખણના ઉચ્ચપ્રદેશ પર ફેલાયેલા **દખ્ખણ ટ્રૅપ** વિસ્તારની વિશિષ્ટ જમીન છે.\n"
  "- તે **મહારાષ્ટ્ર, સૌરાષ્ટ્ર, માળવા, મધ્ય પ્રદેશ અને છત્તીસગઢ**ના ઉચ્ચપ્રદેશો પર જોવા મળે છે, અને દક્ષિણ-પૂર્વ દિશામાં **ગોદાવરી અને કૃષ્ણાની ખીણો** સુધી ફેલાયેલી છે.\n"
  "- તે ખૂબ ઝીણા કણો (**માટી**)થી બનેલી છે અને **ભેજ સંગ્રહ કરવાની** ક્ષમતા માટે જાણીતી છે; તેમાં **કૅલ્શિયમ કાર્બોનેટ, મૅગ્નેશિયમ, પોટાશ અને ચૂનો** ભરપૂર છે, પણ **ફૉસ્ફરસનું પ્રમાણ ઓછું** છે.\n"
  "- **ગરમ હવામાનમાં તેમાં ઊંડી તિરાડો** પડે છે, જેથી તેમાં સારી રીતે **હવાની અવરજવર** થાય છે; **ભીની થતાં તે ચીકણી** બને છે અને તેના પર કામ કરવું અઘરું છે, સિવાય કે પહેલા વરસાદ પછી તરત અથવા ચોમાસા પહેલાં તેને ખેડવામાં આવે.\n\n"
  "**3. લાલ અને પીળી જમીન:** દખ્ખણના ઉચ્ચપ્રદેશના પૂર્વ અને દક્ષિણ ભાગોમાં ઓછા વરસાદવાળા વિસ્તારોમાં **સ્ફટિકમય આગ્નેય ખડકો** પર વિકસે છે; **ઓડિશા, છત્તીસગઢ, મધ્ય ગંગાના મેદાનના દક્ષિણ ભાગો** અને **પશ્ચિમ ઘાટના તળેટી વિસ્તાર**માં પણ મળે છે. "
  "સ્ફટિકમય અને રૂપાંતરિત ખડકોમાં **લોહતત્ત્વના પ્રસરણ**ને કારણે તેનો રંગ **લાલ** છે, અને **પાણી શોષાતાં તે પીળી** દેખાય છે.\n\n"
  "**4. લેટેરાઇટ જમીન:** આ નામ લૅટિન શબ્દ **'લેટર' (ઈંટ)** પરથી આવ્યું છે. તે **ઊંચા તાપમાન અને ભારે વરસાદ**વાળા વિસ્તારોમાં વિકસે છે, અને ભારે વરસાદથી થતા **તીવ્ર નિક્ષાલન**નું પરિણામ છે. ઊંચા તાપમાનમાં બૅક્ટેરિયા જેવા વિઘટકો નાશ પામતા હોવાથી તેમાં **સેન્દ્રિય દ્રવ્ય (હ્યુમસ) ઓછું** હોય છે. "
  "તે મુખ્યત્વે **કર્ણાટક, કેરલ, તમિળનાડુ, મધ્ય પ્રદેશ** અને **ઓડિશા અને આસામ**ના પહાડી વિસ્તારોમાં મળે છે. યોગ્ય જમીન સંરક્ષણ પદ્ધતિઓ અપનાવીને, ખાસ કરીને પહાડી વિસ્તારોમાં, તે **ચા અને કૉફી** માટે ખૂબ ઉપયોગી છે; **તમિળનાડુ, આંધ્ર પ્રદેશ અને કેરલ**ની લાલ લેટેરાઇટ જમીનો **કાજુ** જેવા પાક માટે વધુ યોગ્ય છે.\n\n"
  "**5. રણ પ્રકારની જમીન:** તેનો રંગ **લાલથી બદામી** હોય છે; તે સામાન્ય રીતે **રેતાળ** અને **ક્ષારીય** હોય છે; કેટલાક વિસ્તારોમાં ક્ષારનું પ્રમાણ એટલું વધુ છે કે પાણીનું બાષ્પીભવન કરીને મીઠું મેળવાય છે. સૂકી આબોહવા અને ઊંચા તાપમાનને કારણે બાષ્પીભવન ઝડપી છે અને જમીનમાં **સેન્દ્રિય દ્રવ્ય અને ભેજ ઓછાં** છે. "
  "નીચેનાં સ્તરોમાં ચૂનાનું પ્રમાણ વધતું હોવાથી **કંકર**નું સ્તર હોય છે, જે પાણીને જમીનમાં ઊતરતું અટકાવે છે. યોગ્ય **સિંચાઈ**થી આ જમીનો ખેતીલાયક બને છે, જેમ કે **પશ્ચિમ રાજસ્થાન**માં.\n\n"
  "**6. જંગલ (પર્વતીય) જમીન:** તે **પહાડી અને પર્વતીય વિસ્તારો**માં મળે છે જ્યાં પૂરતાં વરસાદી જંગલો છે. તેની રચના પર્વતીય પર્યાવરણ મુજબ બદલાય છે: ખીણની બાજુઓ પર તે **ગોરાડુ અને કાંપવાળી** અને ઉપરના ઢોળાવો પર **જાડા કણોવાળી** હોય છે. હિમાલયના બરફાચ્છાદિત વિસ્તારોમાં તેનું ઘસારણ થાય છે અને તે **ઍસિડિક અને ઓછા સેન્દ્રિય દ્રવ્યવાળી** હોય છે; ખીણોના નીચલા ભાગોમાં, ખાસ કરીને **નદીનાં પગથિયાં (ટેરેસ) અને કાંપના પંખાઓ**માં, તે ફળદ્રુપ હોય છે."),
 "s5.table.title": ("छह मृदाओं की तुलना", "છ જમીનોની સરખામણી"),
 "s5.table.body": (
  "| मृदा | निर्माण / कहाँ पाई जाती है | विशेषताएँ | फ़सलें |\n|---|---|---|---|\n"
  "| **जलोढ़** | सिंधु, गंगा और ब्रह्मपुत्र द्वारा जमा; उत्तरी मैदान, राजस्थान और गुजरात, पूर्वी तट के डेल्टा (महानदी, गोदावरी, कृष्णा, कावेरी) | रेत, सिल्ट, मृत्तिका; पोटाश, फ़ॉस्फ़ोरस और चूने से भरपूर; बांगर (पुरानी) और खादर (नई) | गन्ना, चावल, गेहूँ, अनाज, दलहन |\n"
  "| **काली (रेगर)** | दक्कन ट्रैप का बेसाल्ट लावा; महाराष्ट्र, सौराष्ट्र, मालवा, मध्य प्रदेश, छत्तीसगढ़, गोदावरी और कृष्णा घाटियाँ | मृत्तिकामय, नमी धारण करती है, कैल्शियम कार्बोनेट, मैग्नीशियम, पोटाश, चूने से भरपूर; फ़ॉस्फ़ोरस कम; गर्मी में गहरी दरारें | कपास |\n"
  "| **लाल और पीली** | पूर्वी और दक्षिणी दक्कन के कम वर्षा वाले क्षेत्रों में रवेदार आग्नेय चट्टानें; ओडिशा, छत्तीसगढ़, मध्य गंगा मैदान का दक्षिणी भाग, पश्चिमी घाट का गिरिपद | लोहे से लाल; जलयोजित होने पर पीली | (खाद के साथ) अनेक फ़सलें |\n"
  "| **लेटराइट** | उच्च तापमान और भारी वर्षा; कर्नाटक, केरल, तमिलनाडु, मध्य प्रदेश, पहाड़ी ओडिशा और असम | तीव्र निक्षालन; ह्यूमस कम | काजू (लाल लेटराइट), खाद के साथ चाय, कॉफ़ी |\n"
  "| **मरुस्थली** | शुष्क क्षेत्र, पश्चिमी राजस्थान | रेतीली, लवणीय; ह्यूमस और नमी कम; निचली परतों में कंकड़ | सिंचाई से खेती योग्य |\n"
  "| **वन** | पर्याप्त वर्षा वनों वाले पहाड़ी और पर्वतीय क्षेत्र | घाटियों में दोमट और सिल्टदार, ऊपरी ढलानों पर मोटे कण; हिमाच्छादित क्षेत्रों में अम्लीय, कम ह्यूमस | नदी सोपानों और जलोढ़ पंखों में उपजाऊ |",
  "| જમીન | નિર્માણ / ક્યાં મળે | લક્ષણો | પાકો |\n|---|---|---|---|\n"
  "| **કાંપની** | સિંધુ, ગંગા અને બ્રહ્મપુત્રએ જમા કરી; ઉત્તરનાં મેદાનો, રાજસ્થાન અને ગુજરાત, પૂર્વ કિનારાના મુખત્રિકોણો (મહાનદી, ગોદાવરી, કૃષ્ણા, કાવેરી) | રેતી, કાંપ, માટી; પોટાશ, ફૉસ્ફરિક ઍસિડ અને ચૂનાથી સમૃદ્ધ; બાંગર (જૂની) અને ખાદર (નવી) | શેરડી, ડાંગર, ઘઉં, ધાન્ય, કઠોળ |\n"
  "| **કાળી (રેગુર)** | દખ્ખણ ટ્રૅપનો બેસાલ્ટ લાવા; મહારાષ્ટ્ર, સૌરાષ્ટ્ર, માળવા, મધ્ય પ્રદેશ, છત્તીસગઢ, ગોદાવરી અને કૃષ્ણા ખીણો | ચીકણી માટીવાળી, ભેજ સંગ્રહે, કૅલ્શિયમ કાર્બોનેટ, મૅગ્નેશિયમ, પોટાશ, ચૂનાથી સમૃદ્ધ; ફૉસ્ફરસ ઓછો; ઉનાળામાં ઊંડી તિરાડો | કપાસ |\n"
  "| **લાલ અને પીળી** | પૂર્વ અને દક્ષિણ દખ્ખણના ઓછા વરસાદવાળા વિસ્તારોમાં સ્ફટિકમય આગ્નેય ખડકો; ઓડિશા, છત્તીસગઢ, મધ્ય ગંગા મેદાનનો દક્ષિણ ભાગ, પશ્ચિમ ઘાટની તળેટી | લોહથી લાલ; પાણી શોષાતાં પીળી | (ખાતર સાથે) અનેક પાકો |\n"
  "| **લેટેરાઇટ** | ઊંચું તાપમાન અને ભારે વરસાદ; કર્ણાટક, કેરલ, તમિળનાડુ, મધ્ય પ્રદેશ, પહાડી ઓડિશા અને આસામ | તીવ્ર નિક્ષાલન; સેન્દ્રિય દ્રવ્ય ઓછું | કાજુ (લાલ લેટેરાઇટ), ખાતર સાથે ચા, કૉફી |\n"
  "| **રણ પ્રકારની** | સૂકા વિસ્તારો, પશ્ચિમ રાજસ્થાન | રેતાળ, ક્ષારીય; સેન્દ્રિય દ્રવ્ય અને ભેજ ઓછાં; નીચલા સ્તરોમાં કંકર | સિંચાઈથી ખેતીલાયક |\n"
  "| **જંગલ** | પૂરતાં વરસાદી જંગલોવાળા પહાડી અને પર્વતીય વિસ્તારો | ખીણોમાં ગોરાડુ અને કાંપવાળી, ઉપલા ઢોળાવો પર જાડા કણો; બરફાચ્છાદિત વિસ્તારોમાં ઍસિડિક, ઓછું સેન્દ્રિય દ્રવ્ય | નદીનાં પગથિયાં અને કાંપના પંખાઓમાં ફળદ્રુપ |"),
 "s6.thm.title": ("मृदा कैसे नष्ट होती है, और उसे कैसे बचाएँ", "જમીન કેવી રીતે નષ્ટ થાય છે, અને તેને કેવી રીતે બચાવવી"),
 "s6.thm.body": (
  "मृदा के कटाव और उसके बहाव की प्रक्रिया को **मृदा अपरदन** कहते हैं। मृदा के बनने और अपरदन की क्रियाएँ साथ-साथ चलती हैं और सामान्यतः संतुलन में रहती हैं, पर मानवीय क्रियाएँ इस संतुलन को भंग कर देती हैं।\n\n"
  "**कारण:** **वनोन्मूलन, अति पशुचारण, निर्माण और खनन**, और **पवन, हिमनदी और जल** जैसे प्राकृतिक तत्त्व।\n"
  "- **अवनालिकाएँ:** बहता जल मृत्तिकायुक्त मृदाओं को काटते हुए गहरी वाहिकाएँ बनाता है, जिन्हें अवनालिकाएँ कहते हैं। ऐसी भूमि खेती योग्य नहीं रहती और इसे **उत्खात भूमि** कहते हैं। **चंबल बेसिन** में ऐसी भूमि को **खड्ड** कहते हैं।\n"
  "- **चादर अपरदन:** जल विस्तृत क्षेत्र में ढाल के साथ चादर के रूप में बहता है, और ऊपरी मृदा बह जाती है।\n"
  "- **पवन अपरदन:** पवन द्वारा मैदान या ढालू क्षेत्र से मृदा को उड़ा ले जाना।\n"
  "- **कृषि के ग़लत तरीक़े:** **ढाल पर ऊपर से नीचे** हल चलाने से वाहिकाएँ बन जाती हैं, जिनसे जल तेज़ी से बहता है और अपरदन होता है।\n\n"
  "**मृदा संरक्षण:**\n"
  "- **समोच्च जुताई:** ढाल वाली भूमि पर **समोच्च रेखाओं के समानांतर** हल चलाने से ढाल के साथ जल बहाव की गति घटती है।\n"
  "- **सीढ़ीदार कृषि:** ढलानों पर **सोपान** बनाने से अपरदन नियंत्रित होता है। **पश्चिमी और मध्य हिमालय** में सोपान या सीढ़ीदार कृषि काफ़ी विकसित है।\n"
  "- **पट्टी कृषि:** बड़े खेतों को पट्टियों में बाँटकर **फ़सलों के बीच में घास की पट्टियाँ उगाई जाती हैं**; ये पवन की शक्ति को कमज़ोर करती हैं।\n"
  "- **रक्षक मेखला:** **पेड़ों की कतारें** लगाकर रक्षक मेखला बनाना भी इसी तरह काम करता है। ऐसी कतारों ने **पश्चिमी भारत** में **रेत के टीलों** और मरुस्थल को **स्थिर** बनाने में महत्त्वपूर्ण योगदान दिया है।\n\n"
  "**सुखोमाजरी** गाँव (हरियाणा) और **झाबुआ** ज़िले (मध्य प्रदेश) ने दिखाया है कि जलसंभर और वनों के सामुदायिक प्रबंधन से भूमि निम्नीकरण को पलटा जा सकता है।",
  "જમીનના ઉપલા પડના ઘસારા અને તેના વહી જવાની પ્રક્રિયાને **જમીન ધોવાણ** કહે છે. જમીન બનવાની અને ધોવાણની ક્રિયાઓ સાથે સાથે ચાલે છે અને સામાન્ય રીતે સંતુલનમાં હોય છે, પણ માનવ પ્રવૃત્તિઓ આ સંતુલન તોડે છે.\n\n"
  "**કારણો:** **જંગલોનો નાશ, અતિચરાઈ, બાંધકામ અને ખાણકામ**, અને **પવન, હિમનદી અને પાણી** જેવાં કુદરતી બળો.\n"
  "- **કોતરો (ગલી):** વહેતું પાણી ચીકણી માટીવાળી જમીનને કાપીને ઊંડી નાળો બનાવે છે, જેને કોતરો કહે છે. આવી જમીન ખેતી માટે નકામી બને છે અને તેને **ઉજ્જડ (બૅડ લૅન્ડ) જમીન** કહે છે. **ચંબલના થાળા**માં આવી જમીનને **કોતરો (રેવાઇન્સ)** કહે છે.\n"
  "- **પડ ધોવાણ:** પાણી વિશાળ વિસ્તારમાં ઢોળાવ પર ચાદરની જેમ વહે છે, અને ઉપરની જમીન ધોવાઈ જાય છે.\n"
  "- **પવન ધોવાણ:** પવન સપાટ કે ઢોળાવવાળી જમીન પરથી છૂટી માટી ઉડાડી જાય છે.\n"
  "- **ખેતીની ખોટી પદ્ધતિઓ:** **ઢોળાવ પર ઉપરથી નીચે** હળ ચલાવવાથી નાળો બને છે, જેથી પાણી ઝડપથી વહે છે અને ધોવાણ થાય છે.\n\n"
  "**જમીન સંરક્ષણ:**\n"
  "- **સમોચ્ચ ખેડ:** ઢોળાવવાળી જમીન પર **સમોચ્ચ રેખાઓને સમાંતર** હળ ચલાવવાથી ઢોળાવ પર પાણીના વહેણની ઝડપ ઘટે છે.\n"
  "- **પગથિયાં આકારની (સીડીદાર) ખેતી:** ઢોળાવો પર **પગથિયાં** બનાવવાથી ધોવાણ અટકે છે. **પશ્ચિમ અને મધ્ય હિમાલય**માં પગથિયાં આકારની ખેતી સારી રીતે વિકસેલી છે.\n"
  "- **પટ્ટીદાર ખેતી:** મોટાં ખેતરોને પટ્ટીઓમાં વહેંચીને **પાકો વચ્ચે ઘાસની પટ્ટીઓ ઉગાડાય છે**; તે પવનનું જોર તોડે છે.\n"
  "- **રક્ષક વૃક્ષ પટ્ટી:** **વૃક્ષોની હરોળો** વાવીને રક્ષણ ઊભું કરવું પણ એ જ રીતે કામ કરે છે. આવી હરોળોએ **પશ્ચિમ ભારત**માં **રેતીના ઢૂવા** અને રણને **સ્થિર** કરવામાં મહત્ત્વનો ફાળો આપ્યો છે.\n\n"
  "**સુખોમાજરી** ગામ (હરિયાણા) અને **ઝાબુઆ** જિલ્લા (મધ્ય પ્રદેશ)એ દર્શાવ્યું છે કે જળસ્રાવ વિસ્તાર અને જંગલોના સામુદાયિક વ્યવસ્થાપનથી ભૂમિ અવક્રમણને ઉલટાવી શકાય."),
 "s7.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s7.memory.body": (
  "- **वर्गीकरण के चार आधार: \"उ-स-स्वा-वि\"** = उत्पत्ति, समाप्यता, स्वामित्व, विकास का स्तर।\n- **विकास की सीढ़ी: संभावी → विकसित; भंडार ⊃ संचित कोष** (संचित कोष भंडार का हिस्सा है)।\n"
  "- **12 और 200:** 12 समुद्री मील = प्रादेशिक जल (राष्ट्रीय); 200 समुद्री मील से परे = अंतर्राष्ट्रीय।\n- **भारत की भूमि 43-30-27:** मैदान, पर्वत, पठार।\n"
  "- **निम्नीकरण का नक़्शा: \"पूर्व में खदान, पश्चिम में चराई, उत्तर-पश्चिम में पानी\":** खनन (झारखंड, छत्तीसगढ़, मध्य प्रदेश, ओडिशा), अति पशुचारण (गुजरात, राजस्थान, मध्य प्रदेश, महाराष्ट्र), अति सिंचाई (पंजाब, हरियाणा, पश्चिमी उत्तर प्रदेश)।\n"
  "- **मृदाएँ: \"ज-का-ला-ले-म-व\"** = जलोढ़, काली, लाल-पीली, लेटराइट, मरुस्थली, वन।",
  "- **વર્ગીકરણના ચાર આધાર: \"ઉ-ખૂ-મા-વિ\"** = ઉત્પત્તિ, ખૂટી જવું, માલિકી, વિકાસની સ્થિતિ.\n- **વિકાસની સીડી: સંભવિત → વિકસિત; ભંડાર ⊃ અનામત** (અનામત ભંડારનો ભાગ છે).\n"
  "- **12 અને 200:** 12 નૉટિકલ માઈલ = પ્રાદેશિક જળ (રાષ્ટ્રીય); 200 નૉટિકલ માઈલથી આગળ = આંતરરાષ્ટ્રીય.\n- **ભારતની ભૂમિ 43-30-27:** મેદાનો, પર્વતો, ઉચ્ચપ્રદેશો.\n"
  "- **અવક્રમણનો નકશો: \"પૂર્વમાં ખાણ, પશ્ચિમમાં ચરાઈ, ઉત્તર-પશ્ચિમમાં પાણી\":** ખાણકામ (ઝારખંડ, છત્તીસગઢ, મધ્ય પ્રદેશ, ઓડિશા), અતિચરાઈ (ગુજરાત, રાજસ્થાન, મધ્ય પ્રદેશ, મહારાષ્ટ્ર), અતિસિંચાઈ (પંજાબ, હરિયાણા, પશ્ચિમ ઉત્તર પ્રદેશ).\n"
  "- **જમીનો: \"કાં-કા-લા-લે-ર-જં\"** = કાંપની, કાળી, લાલ-પીળી, લેટેરાઇટ, રણ પ્રકારની, જંગલ."),
 "s7.mistakes.title": ("आम ग़लतियाँ", "સામાન્ય ભૂલો"),
 "s7.mistakes.body": (
  "1. संचित कोष और भंडार को एक कहना: **संचित कोष भंडार का हिस्सा** है जिसका उपयोग वर्तमान प्रौद्योगिकी से हो सकता है।\n2. खादर को 'पुरानी जलोढ़' कहना: **खादर नई** और अधिक उपजाऊ है; **बांगर पुरानी** है और उसमें कंकड़ ग्रंथियाँ हैं।\n"
  "3. काली मृदा को फ़ॉस्फ़ोरस से भरपूर कहना: उसमें **फ़ॉस्फ़ोरस कम** है।\n4. लेटराइट को ह्यूमस से भरपूर कहना: उच्च तापमान जीवाणुओं को नष्ट करता है, इसलिए ह्यूमस **कम** है।\n"
  "5. 1987 की ब्रुन्डटलैंड रिपोर्ट (सतत पोषणीय विकास) को 1992 के रियो सम्मेलन (एजेंडा 21) से मिलाना।\n6. सकल कृषित क्षेत्र = शुद्ध बोया गया क्षेत्र कहना: सकल कृषित क्षेत्र में वर्ष में **एक से अधिक बार** बोई गई भूमि भी गिनी जाती है।",
  "1. અનામત અને ભંડારને એક ગણવા: **અનામત ભંડારનો ભાગ** છે જેનો ઉપયોગ હાલની ટેકનોલોજીથી થઈ શકે.\n2. ખાદરને 'જૂની કાંપ' કહેવી: **ખાદર નવી** અને વધુ ફળદ્રુપ છે; **બાંગર જૂની** છે અને તેમાં કંકર ગઠ્ઠાઓ છે.\n"
  "3. કાળી જમીનને ફૉસ્ફરસથી સમૃદ્ધ કહેવી: તેમાં **ફૉસ્ફરસ ઓછો** છે.\n4. લેટેરાઇટને સેન્દ્રિય દ્રવ્યથી સમૃદ્ધ કહેવી: ઊંચું તાપમાન બૅક્ટેરિયાનો નાશ કરે છે, તેથી સેન્દ્રિય દ્રવ્ય **ઓછું** છે.\n"
  "5. 1987ના બ્રુન્ટલૅન્ડ રિપોર્ટ (ટકાઉ વિકાસ)ને 1992ની રિયો પરિષદ (એજન્ડા 21) સાથે ભેળવવો.\n6. કુલ પાક વિસ્તાર = ચોખ્ખો વાવેતર વિસ્તાર કહેવો: કુલ પાક વિસ્તારમાં વર્ષમાં **એકથી વધુ વાર** વાવેલી જમીન પણ ગણાય છે."),
 "s7.tip.title": ("कक्षा में करके देखें", "વર્ગમાં કરી જુઓ"),
 "s7.tip.body": (
  "बगीचे, नदी किनारे और लाल मिट्टी वाले क्षेत्र से मृदा के नमूने लाएँ। विद्यार्थी हर नमूने का रंग, गठन और उसमें से पानी कितनी जल्दी निकलता है, इसकी तुलना करें। "
  "फिर मिट्टी की एक ट्रे को तिरछा करके पानी डालें: एक बार ढाल पर ऊपर से नीचे सीधी नालियाँ बनाकर और एक बार ढाल के आर-पार, ताकि दिखे कि समोच्च जुताई क्यों काम करती है।",
  "બગીચા, નદીકિનારા અને લાલ માટીવાળા વિસ્તારમાંથી જમીનના નમૂના લાવો. વિદ્યાર્થીઓ દરેક નમૂનાનો રંગ, રચના અને તેમાંથી પાણી કેટલી ઝડપથી નીકળે છે તેની સરખામણી કરે. "
  "પછી માટીની એક ટ્રે ત્રાંસી કરીને પાણી રેડો: એક વાર ઢોળાવ પર ઉપરથી નીચે સીધી નાળીઓ બનાવીને અને એક વાર ઢોળાવની આડી, જેથી દેખાય કે સમોચ્ચ ખેડ કેમ કામ કરે છે."),
 "s7.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s7.reflection.body": (
  "गांधीजी ने कहा, 'हमारे पास हर व्यक्ति की आवश्यकता पूर्ति के लिए बहुत कुछ है, लेकिन किसी के लालच की संतुष्टि के लिए नहीं।' अपने घर या स्कूल की ऐसी दो बातें लिखिए जिनसे किसी संसाधन की बर्बादी होती है, और हर एक को सुधारने का उपाय सुझाइए।",
  "ગાંધીજીએ કહ્યું, 'પૃથ્વી પાસે દરેકની જરૂરિયાત પૂરી કરવા પૂરતું છે, પણ કોઈના લોભ માટે નહિ.' તમારા ઘર કે શાળાની એવી બે બાબતો લખો જેનાથી કોઈ સંસાધનનો બગાડ થાય છે, અને દરેકને સુધારવાનો ઉપાય સૂચવો."),
 "s7.connection.title": ("आगे कहाँ", "આગળ ક્યાં"),
 "s7.connection.body": (
  "- **अध्याय 2 (वन और वन्य जीव संसाधन):** जैव संसाधनों का संरक्षण।\n- **अध्याय 3 (जल संसाधन):** बाँध, वर्षा जल संग्रहण और जल संरक्षण।\n"
  "- **अध्याय 4 (कृषि):** कौन-सी मृदा किस फ़सल के लिए उपयुक्त है, और भारत की शस्य ऋतुएँ।\n- **अध्याय 5 (खनिज और ऊर्जा संसाधन):** अनवीकरण योग्य संसाधन और उनका संरक्षण।",
  "- **પ્રકરણ 2 (જંગલ અને વન્યજીવ સંસાધનો):** જૈવિક સંસાધનોનું સંરક્ષણ.\n- **પ્રકરણ 3 (જળ સંસાધનો):** બંધો, વરસાદી જળ સંગ્રહ અને જળ સંરક્ષણ.\n"
  "- **પ્રકરણ 4 (કૃષિ):** કઈ જમીન કયા પાક માટે યોગ્ય છે, અને ભારતની પાક ઋતુઓ.\n- **પ્રકરણ 5 (ખનિજો અને ઊર્જા સંસાધનો):** અપુનઃપ્રાપ્ય સંસાધનો અને તેનું સંરક્ષણ."),
 "s7.mastery.title": ("महारत चुनौती", "નિપુણતા પડકાર"),
 "s7.mastery.body": (
  "'संसाधन विकास में तभी योगदान दे सकते हैं जब उनके साथ उचित प्रौद्योगिकी का विकास और संस्थागत परिवर्तन हों।' उदाहरणों सहित लगभग 120 शब्दों में समझाइए।\n\n"
  "**आदर्श उत्तर:** केवल संसाधन विकास नहीं लाते; उनके उपयोग के लिए प्रौद्योगिकी और प्रबंधन के लिए संस्थाएँ चाहिए। राजस्थान में सौर और पवन ऊर्जा की अपार संभावना है, पर वह सौर पार्कों और पवन फ़ार्मों से ही उपयोगी बनती है। जल में हाइड्रोजन भंडार है क्योंकि उसके उपयोग की प्रौद्योगिकी हमारे पास नहीं है। "
  "अरुणाचल प्रदेश में जल प्रचुर है पर अवसंरचना की कमी है, इसलिए उसका पूरा उपयोग नहीं होता। इतिहास बताता है कि संसाधनों से समृद्ध उपनिवेशों का शोषण उच्च प्रौद्योगिकी वाले उपनिवेशकारियों ने किया। "
  "इसलिए भारत सर्वेक्षण, नियोजन ढाँचे और पंचवर्षीय योजनाओं से संसाधनों का नियोजन करता है और उन्हें राष्ट्रीय विकास से जोड़ता है, ताकि संसाधन विकास का कारण बनें।",
  "'સંસાધનો વિકાસમાં ત્યારે જ ફાળો આપી શકે જ્યારે તેની સાથે યોગ્ય ટેકનોલોજીનો વિકાસ અને સંસ્થાકીય ફેરફારો થાય.' ઉદાહરણો સાથે આશરે 120 શબ્દોમાં સમજાવો.\n\n"
  "**આદર્શ ઉત્તર:** માત્ર સંસાધનો વિકાસ લાવતાં નથી; તેના ઉપયોગ માટે ટેકનોલોજી અને વ્યવસ્થાપન માટે સંસ્થાઓ જોઈએ. રાજસ્થાનમાં સૌર અને પવન ઊર્જાની પુષ્કળ સંભાવના છે, પણ તે સૌર પાર્ક અને પવન ફાર્મથી જ ઉપયોગી બને છે. પાણીમાંનો હાઇડ્રોજન ભંડાર છે કારણ કે તેના ઉપયોગની ટેકનોલોજી આપણી પાસે નથી. "
  "અરુણાચલ પ્રદેશમાં પાણી પુષ્કળ છે પણ માળખાકીય સુવિધાઓનો અભાવ છે, તેથી તેનો પૂરો ઉપયોગ થતો નથી. ઇતિહાસ બતાવે છે કે સંસાધનોથી સમૃદ્ધ સંસ્થાનોનું શોષણ ઊંચી ટેકનોલોજીવાળા સંસ્થાનવાદીઓએ કર્યું. "
  "તેથી ભારત સર્વેક્ષણ, આયોજન માળખા અને પંચવર્ષીય યોજનાઓથી સંસાધનોનું આયોજન કરે છે અને તેને રાષ્ટ્રીય વિકાસ સાથે જોડે છે, જેથી સંસાધનો વિકાસનું કારણ બને."),
 "s7.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s7.summary.body": (
  "- संसाधन वह है जो हमारी आवश्यकताएँ पूरी करे और प्रौद्योगिकी की दृष्टि से सुलभ, आर्थिक रूप से संभाव्य और सांस्कृतिक रूप से मान्य हो।\n"
  "- संसाधनों का वर्गीकरण उत्पत्ति, समाप्यता, स्वामित्व और विकास के स्तर के आधार पर होता है।\n"
  "- अंधाधुंध उपयोग से ह्रास, असमानता और पारिस्थितिकी संकट पैदा होते हैं; सतत पोषणीय विकास, रियो सम्मेलन (1992) और एजेंडा 21 इनके समाधान के लिए हैं।\n"
  "- भारत में संसाधन नियोजन में तालिका बनाना, नियोजन ढाँचा और राष्ट्रीय योजनाओं से समन्वय शामिल है; गांधीजी ने संरक्षण पर ज़ोर दिया।\n"
  "- भूमि: 43% मैदान, 30% पर्वत, 27% पठार; भूमि निम्नीकरण खनन, अति पशुचारण, अति सिंचाई, धूल और औद्योगिक जल से होता है।\n"
  "- छह मृदाएँ: जलोढ़, काली, लाल और पीली, लेटराइट, मरुस्थली और वन; मृदा अपरदन समोच्च जुताई, सीढ़ीदार कृषि, पट्टी कृषि और रक्षक मेखला से रोका जाता है।",
  "- સંસાધન એ છે જે આપણી જરૂરિયાતો સંતોષે અને ટેકનોલોજીની દૃષ્ટિએ સુલભ, આર્થિક રીતે શક્ય અને સાંસ્કૃતિક રીતે સ્વીકાર્ય હોય.\n"
  "- સંસાધનોનું વર્ગીકરણ ઉત્પત્તિ, ખૂટી જવું, માલિકી અને વિકાસની સ્થિતિના આધારે થાય છે.\n"
  "- આડેધડ ઉપયોગથી ઘટાડો, અસમાનતા અને પર્યાવરણીય કટોકટી સર્જાય છે; ટકાઉ વિકાસ, રિયો પરિષદ (1992) અને એજન્ડા 21 તેના ઉકેલ માટે છે.\n"
  "- ભારતમાં સંસાધન આયોજનમાં યાદી બનાવવી, આયોજન માળખું અને રાષ્ટ્રીય યોજનાઓ સાથે સંકલન આવે છે; ગાંધીજીએ સંરક્ષણ પર ભાર મૂક્યો.\n"
  "- ભૂમિ: 43% મેદાનો, 30% પર્વતો, 27% ઉચ્ચપ્રદેશો; ભૂમિ અવક્રમણ ખાણકામ, અતિચરાઈ, અતિસિંચાઈ, ધૂળ અને ઔદ્યોગિક પાણીથી થાય છે.\n"
  "- છ જમીનો: કાંપની, કાળી, લાલ અને પીળી, લેટેરાઇટ, રણ પ્રકારની અને જંગલ; જમીન ધોવાણ સમોચ્ચ ખેડ, પગથિયાં આકારની ખેતી, પટ્ટીદાર ખેતી અને રક્ષક વૃક્ષ પટ્ટીથી અટકાવાય છે."),
 "s7.examtips.title": ("बोर्ड परीक्षा के सुझाव", "બોર્ડ પરીક્ષા માટેની ટિપ્સ"),
 "s7.examtips.body": (
  "- 2025-26 के प्रतिदर्श प्रश्न-पत्र में पूछा गया कि संसाधन विकास से समग्र विकास के लिए क्या आवश्यक है (प्रौद्योगिकी और संस्थागत परिवर्तन), और मृदा वर्गीकरण का चार्ट भरना था (कपास के लिए काली मृदा, काजू के लिए लेटराइट)।\n"
  "- 3/5 अंक के प्रिय प्रश्न: संसाधनों का वर्गीकरण, संसाधन नियोजन के सोपान, भूमि निम्नीकरण और उसके समाधान, जलोढ़ और काली मृदा की विशेषताएँ, मृदा संरक्षण के तरीक़े।\n"
  "- **मानचित्र कार्य:** भारत के मानचित्र पर प्रमुख मृदा प्रकारों को पहचानने और अंकित करने के लिए तैयार रहें।",
  "- 2025-26ના નમૂનાના પ્રશ્નપત્રમાં પૂછાયું કે સંસાધન વિકાસથી સર્વાંગી વિકાસ માટે શું જરૂરી છે (ટેકનોલોજી અને સંસ્થાકીય ફેરફારો), અને જમીન વર્ગીકરણનો ચાર્ટ ભરવાનો હતો (કપાસ માટે કાળી જમીન, કાજુ માટે લેટેરાઇટ).\n"
  "- 3/5 ગુણના પ્રિય પ્રશ્નો: સંસાધનોનું વર્ગીકરણ, સંસાધન આયોજનનાં સોપાનો, ભૂમિ અવક્રમણ અને તેના ઉકેલો, કાંપની અને કાળી જમીનનાં લક્ષણો, જમીન સંરક્ષણની પદ્ધતિઓ.\n"
  "- **નકશા કાર્ય:** ભારતના નકશામાં મુખ્ય જમીન પ્રકારો ઓળખવા અને દર્શાવવા તૈયાર રહો."),
 "s7.flash1.front": ("किसी वस्तु के संसाधन होने की तीन शर्तें क्या हैं?", "કોઈ વસ્તુ સંસાધન બનવાની ત્રણ શરતો કઈ છે?"),
 "s7.flash1.back": ("प्रौद्योगिकी की दृष्टि से सुलभ, आर्थिक रूप से संभाव्य और सांस्कृतिक रूप से मान्य।", "ટેકનોલોજીની દૃષ્ટિએ સુલભ, આર્થિક રીતે શક્ય અને સાંસ્કૃતિક રીતે સ્વીકાર્ય."),
 "s7.flash2.front": ("एजेंडा 21 क्या है?", "એજન્ડા 21 શું છે?"),
 "s7.flash2.back": ("रियो पृथ्वी सम्मेलन (1992) में स्वीकृत एजेंडा, जिसका उद्देश्य विश्व सहयोग से पर्यावरणीय क्षति, ग़रीबी और रोगों से निपटना है।", "રિયો પૃથ્વી પરિષદ (1992)માં સ્વીકારાયેલ કાર્યક્રમ, જેનો હેતુ વૈશ્વિક સહકારથી પર્યાવરણીય નુકસાન, ગરીબી અને રોગો સામે લડવાનો છે."),
 "s7.flash3.front": ("बांगर और खादर में क्या अंतर है?", "બાંગર અને ખાદરમાં શો તફાવત છે?"),
 "s7.flash3.back": ("बांगर पुरानी जलोढ़ है जिसमें कंकड़ ग्रंथियाँ हैं; खादर नई, महीन और अधिक उपजाऊ है।", "બાંગર જૂની કાંપની જમીન છે જેમાં કંકર ગઠ્ઠાઓ છે; ખાદર નવી, ઝીણી અને વધુ ફળદ્રુપ છે."),
 "s7.flash4.front": ("मृदा संरक्षण के चार तरीक़े बताइए।", "જમીન સંરક્ષણની ચાર પદ્ધતિઓ જણાવો."),
 "s7.flash4.back": ("समोच्च जुताई, सीढ़ीदार कृषि, पट्टी कृषि और रक्षक मेखला।", "સમોચ્ચ ખેડ, પગથિયાં આકારની ખેતી, પટ્ટીદાર ખેતી અને રક્ષક વૃક્ષ પટ્ટી."),
}
